   1→import { useEffect, useRef, useState } from "react";
   2→import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
   3→import { useLoaderData, useFetcher, redirect, useNavigate } from "react-router";
   4→import { useAppBridge } from "@shopify/app-bridge-react";
   5→import { authenticate } from "../shopify.server";
   6→import db from "../db.server";
   7→import {
   8→  Page,
   9→  Layout,
  10→  Card,
  11→  BlockStack,
  12→  InlineStack,
  13→  Text,
  14→  Badge,
  15→  Button,
  16→  ButtonGroup,
  17→  Banner,
  18→  TextField,
  19→  Select,
  20→  Checkbox,
  21→  List,
  22→} from "@shopify/polaris";
  23→
  24→// ---------------------------------------------------------------------------
  25→// Types
  26→// ---------------------------------------------------------------------------
  27→
  28→interface DisplaySettings {
  29→  priority: number;
  30→  countries: "all" | "selected";
  31→  selectedCountries: string;
  32→  buttonPosition: "floating" | "above_desc" | "below_desc";
  33→}
  34→
  35→interface ChartData {
  36→  headers: string[];
  37→  units: { default: string; available: string[] };
  38→  rows: Record<string, string>[];
  39→  displaySettings?: DisplaySettings;
  40→  recommendationEnabled?: boolean;
  41→}
  42→
  43→interface Assignment {
  44→  id: string;
  45→  assignmentType: string;
  46→  assignmentValue: string;
  47→}
  48→
  49→// ---------------------------------------------------------------------------
  50→// Loader
  51→// ---------------------------------------------------------------------------
  52→
  53→export const loader = async ({ request, params }: LoaderFunctionArgs) => {
  54→  const { session } = await authenticate.admin(request);
  55→  const shop = session.shop;
  56→  const id = params.id;
  57→
  58→  if (!id) throw new Response("Not found", { status: 404 });
  59→
  60→  if (id === "new") {
  61→    return {
  62→      chart: null as null,
  63→      assignments: [] as Assignment[],
  64→      isNew: true,
  65→    };
  66→  }
  67→
  68→  const chart = await db.sizeChart.findFirst({
  69→    where: { id, shop },
  70→    include: { assignments: true },
  71→  });
  72→
  73→  if (!chart) {
  74→    throw new Response("Not found", { status: 404 });
  75→  }
  76→
  77→  return {
  78→    chart: {
  79→      id: chart.id,
  80→      name: chart.name,
  81→      category: chart.category,
  82→      status: chart.status,
  83→      data: chart.data,
  84→      createdAt: chart.createdAt.toISOString(),
  85→      updatedAt: chart.updatedAt.toISOString(),
  86→    },
  87→    assignments: chart.assignments.map((a) => ({
  88→      id: a.id,
  89→      assignmentType: a.assignmentType,
  90→      assignmentValue: a.assignmentValue,
  91→    })),
  92→    isNew: false,
  93→  };
  94→};
  95→
  96→// ---------------------------------------------------------------------------
  97→// Action
  98→// ---------------------------------------------------------------------------
  99→
 100→export const action = async ({ request, params }: ActionFunctionArgs) => {
 101→  const { session } = await authenticate.admin(request);
 102→  const shop = session.shop;
 103→  const id = params.id;
 104→  if (!id) return { error: "Missing chart ID" };
 105→  const formData = await request.formData();
 106→  const intent = formData.get("intent") as string;
 107→
 108→  try {
 109→    switch (intent) {
 110→      case "save": {
 111→        const name = formData.get("name") as string;
 112→        const category = formData.get("category") as string;
 113→        const status = formData.get("status") as string;
 114→        const dataRaw = formData.get("data") as string;
 115→
 116→        if (!name?.trim()) return { error: "Chart name is required" };
 117→
 118→        let parsedData: ChartData;
 119→        try {
 120→          parsedData = JSON.parse(dataRaw) as ChartData;
 121→        } catch {
 122→          return { error: "Invalid chart data. Please try again." };
 123→        }
 124→
 125→        if (id === "new") {
 126→          const chart = await db.sizeChart.create({
 127→            data: {
 128→              shop,
 129→              name: name.trim(),
 130→              category,
 131→              status,
 132→              data: JSON.stringify(parsedData),
 133→            },
 134→          });
 135→          return redirect(`/app/size-charts/${chart.id}?saved=1`);
 136→        }
 137→
 138→        const existing = await db.sizeChart.findFirst({ where: { id, shop } });
 139→        if (!existing) return { error: "Chart not found" };
 140→
 141→        await db.sizeChart.updateMany({
 142→          where: { id, shop },
 143→          data: {
 144→            name: name.trim(),
 145→            category,
 146→            status,
 147→            data: JSON.stringify(parsedData),
 148→          },
 149→        });
 150→        return { ok: true, message: "Chart saved successfully" };
 151→      }
 152→
 153→      case "toggle-status": {
 154→        const chart = await db.sizeChart.findFirst({ where: { id, shop } });
 155→        if (!chart) return { error: "Chart not found" };
 156→        const newStatus = chart.status === "active" ? "draft" : "active";
 157→        await db.sizeChart.updateMany({ where: { id, shop }, data: { status: newStatus } });
 158→        return {
 159→          ok: true,
 160→          message: newStatus === "active" ? "Chart published" : "Chart unpublished",
 161→          newStatus,
 162→        };
 163→      }
 164→
 165→      case "add-assignment": {
 166→        const assignmentType = formData.get("assignmentType") as string;
 167→        const assignmentValue = formData.get("assignmentValue") as string;
 168→
 169→        if (!assignmentValue?.trim()) {
 170→          return { error: "Assignment value is required" };
 171→        }
 172→
 173→        await db.chartAssignment.upsert({
 174→          where: {
 175→            shop_sizeChartId_assignmentType_assignmentValue: {
 176→              shop,
 177→              sizeChartId: id,
 178→              assignmentType,
 179→              assignmentValue: assignmentValue.trim(),
 180→            },
 181→          },
 182→          create: {
 183→            shop,
 184→            sizeChartId: id,
 185→            assignmentType,
 186→            assignmentValue: assignmentValue.trim(),
 187→          },
 188→          update: {},
 189→        });
 190→        return { ok: true, message: "Assignment added" };
 191→      }
 192→
 193→      case "remove-assignment": {
 194→        const assignmentId = formData.get("assignmentId") as string;
 195→        await db.chartAssignment.deleteMany({
 196→          where: { id: assignmentId, shop },
 197→        });
 198→        return { ok: true, message: "Assignment removed" };
 199→      }
 200→
 201→      case "delete": {
 202→        await db.sizeChart.deleteMany({ where: { id, shop } });
 203→        return redirect("/app/size-charts");
 204→      }
 205→
 206→      default:
 207→        return { error: "Unknown action" };
 208→    }
 209→  } catch (error) {
 210→    const message =
 211→      error instanceof Error ? error.message : "An unexpected error occurred";
 212→    if (message.includes("Unique constraint")) {
 213→      return { error: "A chart with this name already exists." };
 214→    }
 215→    return { error: message };
 216→  }
 217→};
