 242→function formatDate(iso: string): string {
 243→  return new Date(iso).toLocaleDateString("en-US", {
 244→    month: "short",
 245→    day: "numeric",
 246→    year: "numeric",
 247→    hour: "2-digit",
 248→    minute: "2-digit",
 249→  });
 250→}
 251→
 252→function makeDefaultData(): ChartData {
 253→  return {
 254→    headers: ["Size", "Chest", "Waist", "Hips"],
 255→    units: { default: "in", available: ["in", "cm"] },
 256→    rows: [
 257→      { Size: "S", Chest: "", Waist: "", Hips: "" },
 258→      { Size: "M", Chest: "", Waist: "", Hips: "" },
 259→      { Size: "L", Chest: "", Waist: "", Hips: "" },
 260→    ],
 261→  };
 262→}
 263→
 264→function parseChartData(raw: string): ChartData {
 265→  try {
 266→    const parsed = JSON.parse(raw) as ChartData;
 267→    if (
 268→      Array.isArray(parsed.headers) &&
 269→      parsed.units &&
 270→      Array.isArray(parsed.rows)
 271→    ) {
 272→      return parsed;
 273→    }
 274→  } catch {
 275→    // fall through
 276→  }
 277→  return makeDefaultData();
 278→}
