 280→// ---------------------------------------------------------------------------
 281→// Table Editor Component
 282→// ---------------------------------------------------------------------------
 283→
 284→interface TableEditorProps {
 285→  data: ChartData;
 286→  onChange: (data: ChartData) => void;
 287→}
 288→
 289→function TableEditor({ data, onChange }: TableEditorProps) {
 290→  const headerInputRefs = useRef<(HTMLInputElement | null)[]>([]);
 291→
 292→  const updateCell = (rowIndex: number, header: string, value: string) => {
 293→    const newRows = data.rows.map((row, i) => {
 294→      if (i !== rowIndex) return row;
 295→      return { ...row, [header]: value };
 296→    });
 297→    onChange({ ...data, rows: newRows });
 298→  };
 299→
 300→  const updateHeader = (headerIndex: number, value: string) => {
 301→    const oldHeader = data.headers[headerIndex];
 302→    const newHeaders = data.headers.map((h, i) =>
 303→      i === headerIndex ? value : h,
 304→    );
 305→    const newRows = data.rows.map((row) => {
 306→      const newRow: Record<string, string> = {};
 307→      data.headers.forEach((h, i) => {
 308→        const key = i === headerIndex ? value : h;
 309→        newRow[key] = row[h] ?? "";
 310→      });
 311→      return newRow;
 312→    });
 313→    onChange({ ...data, headers: newHeaders, rows: newRows });
 314→    void oldHeader;
 315→  };
 316→
 317→  const addRow = () => {
 318→    const emptyRow: Record<string, string> = {};
 319→    data.headers.forEach((h) => {
 320→      emptyRow[h] = "";
 321→    });
 322→    onChange({ ...data, rows: [...data.rows, emptyRow] });
 323→  };
 324→
 325→  const removeRow = (rowIndex: number) => {
 326→    onChange({ ...data, rows: data.rows.filter((_, i) => i !== rowIndex) });
 327→  };
 328→
 329→  const addColumn = () => {
 330→    const newHeader = `Column ${data.headers.length + 1}`;
 331→    const newHeaders = [...data.headers, newHeader];
 332→    const newRows = data.rows.map((row) => ({ ...row, [newHeader]: "" }));
 333→    onChange({ ...data, headers: newHeaders, rows: newRows });
 334→  };
 335→
 336→  const removeColumn = (headerIndex: number) => {
 337→    if (data.headers.length <= 1) return;
 338→    const removedHeader = data.headers[headerIndex];
 339→    const newHeaders = data.headers.filter((_, i) => i !== headerIndex);
 340→    const newRows = data.rows.map((row) => {
 341→      const newRow: Record<string, string> = {};
 342→      newHeaders.forEach((h) => {
 343→        newRow[h] = row[h] ?? "";
 344→      });
 345→      return newRow;
 346→    });
 347→    onChange({ ...data, headers: newHeaders, rows: newRows });
 348→    void removedHeader;
 349→  };
 350→
 351→  const toggleUnit = (unit: string) => {
 352→    onChange({ ...data, units: { ...data.units, default: unit } });
 353→  };
 354→
 355→  return (
 356→    <div>
 357→      {/* Toolbar — unit toggle + row/col count */}
 358→      <div
 359→        style={{
 360→          display: "flex",
 361→          alignItems: "center",
 362→          gap: "8px",
 363→          marginBottom: "10px",
 364→        }}
 365→      >
 366→        <span
 367→          style={{
 368→            fontSize: "12px",
 369→            fontWeight: 600,
 370→            color: "#6d7175",
 371→            textTransform: "uppercase",
 372→            letterSpacing: "0.04em",
 373→          }}
 374→        >
 375→          Units
 376→        </span>
 377→        <div
 378→          style={{
 379→            display: "flex",
 380→            gap: "4px",
 381→            background: "#f6f6f7",
 382→            borderRadius: "20px",
 383→            padding: "3px",
 384→            border: "1px solid #e1e3e5",
 385→          }}
 386→        >
 387→          {data.units.available.map((unit) => (
 388→            <button
 389→              key={unit}
 390→              type="button"
 391→              onClick={() => toggleUnit(unit)}
 392→              style={{
 393→                padding: "3px 14px",
 394→                borderRadius: "16px",
 395→                border: "none",
 396→                background:
 397→                  data.units.default === unit ? "#2c6ecb" : "transparent",
 398→                color: data.units.default === unit ? "#ffffff" : "#6d7175",
 399→                fontWeight: data.units.default === unit ? 700 : 500,
 400→                cursor: "pointer",
 401→                fontSize: "12px",
 402→                lineHeight: "20px",
 403→                transition: "all 0.12s ease",
 404→                fontFamily: "inherit",
 405→              }}
 406→            >
 407→              {unit}
 408→            </button>
 409→          ))}
 410→        </div>
 411→        <div
 412→          style={{
 413→            marginLeft: "auto",
 414→            fontSize: "12px",
 415→            color: "#8c9196",
 416→            fontWeight: 500,
 417→            background: "#f6f6f7",
 418→            border: "1px solid #e1e3e5",
 419→            borderRadius: "6px",
 420→            padding: "3px 10px",
 421→          }}
 422→        >
 423→          {data.rows.length} rows &middot; {data.headers.length} cols
 424→        </div>
 425→      </div>
 426→
 427→      {/* Table */}
 428→      <div
 429→        style={{
 430→          border: "1px solid #e1e3e5",
 431→          borderRadius: "8px",
 432→          overflow: "hidden",
 433→          overflowX: "auto",
 434→        }}
 435→      >
 436→        <table
 437→          style={{
 438→            width: "100%",
 439→            borderCollapse: "collapse",
 440→            fontSize: "13px",
 441→            tableLayout: "auto",
 442→          }}
 443→        >
 444→          <thead>
 445→            <tr>
 446→              {data.headers.map((header, hi) => (
 447→                <th
 448→                  key={hi}
 449→                  style={{
 450→                    background: "#f6f6f7",
 451→                    borderBottom: "2px solid #e1e3e5",
 452→                    borderRight:
 453→                      hi < data.headers.length - 1
 454→                        ? "1px solid #e1e3e5"
 455→                        : "none",
 456→                    padding: "0",
 457→                    position: "relative",
 458→                    minWidth: "110px",
 459→                  }}
 460→                >
 461→                  <div
 462→                    style={{
 463→                      display: "flex",
 464→                      alignItems: "center",
 465→                      padding: "2px 6px 2px 10px",
 466→                    }}
 467→                  >
 468→                    <input
 469→                      ref={(el) => {
 470→                        headerInputRefs.current[hi] = el;
 471→                      }}
 472→                      value={header}
 473→                      onChange={(e) =>
 474→                        updateHeader(hi, (e.target as HTMLInputElement).value)
 475→                      }
 476→                      style={{
 477→                        flex: 1,
 478→                        border: "none",
 479→                        background: "transparent",
 480→                        fontWeight: 700,
 481→                        fontSize: "12px",
 482→                        color: "#202223",
 483→                        padding: "8px 4px",
 484→                        outline: "none",
 485→                        minWidth: "60px",
 486→                        textTransform: "uppercase",
 487→                        letterSpacing: "0.04em",
 488→                        fontFamily: "inherit",
 489→                      }}
 490→                      placeholder={`Col ${hi + 1}`}
 491→                    />
 492→                    {data.headers.length > 1 && (
 493→                      <button
 494→                        type="button"
 495→                        onClick={() => removeColumn(hi)}
 496→                        title="Remove column"
 497→                        style={{
 498→                          background: "none",
 499→                          border: "none",
 500→                          cursor: "pointer",
 501→                          color: "#c9cccf",
 502→                          padding: "2px 4px",
 503→                          borderRadius: "4px",
 504→                          fontSize: "15px",
 505→                          lineHeight: 1,
 506→                          flexShrink: 0,
 507→                          transition: "color 0.1s, background 0.1s",
 508→                          fontFamily: "inherit",
 509→                        }}
 510→                        onMouseEnter={(e) => {
 511→                          (e.currentTarget as HTMLButtonElement).style.color =
 512→                            "#d82c0d";
 513→                          (
 514→                            e.currentTarget as HTMLButtonElement
 515→                          ).style.background = "#fee2e2";
 516→                        }}
 517→                        onMouseLeave={(e) => {
 518→                          (e.currentTarget as HTMLButtonElement).style.color =
 519→                            "#c9cccf";
 520→                          (
 521→                            e.currentTarget as HTMLButtonElement
 522→                          ).style.background = "none";
 523→                        }}
 524→                      >
 525→                        &times;
 526→                      </button>
 527→                    )}
 528→                  </div>
 529→                </th>
 530→              ))}
 531→
 532→              {/* Add column header cell */}
 533→              <th
 534→                style={{
 535→                  background: "#f6f6f7",
 536→                  borderBottom: "2px solid #e1e3e5",
 537→                  padding: "0",
 538→                  width: "40px",
 539→                  minWidth: "40px",
 540→                }}
 541→              >
 542→                <button
 543→                  type="button"
 544→                  onClick={addColumn}
 545→                  title="Add column"
 546→                  style={{
 547→                    display: "flex",
 548→                    alignItems: "center",
 549→                    justifyContent: "center",
 550→                    width: "100%",
 551→                    height: "100%",
 552→                    minHeight: "38px",
 553→                    background: "none",
 554→                    border: "none",
 555→                    cursor: "pointer",
 556→                    color: "#2c6ecb",
 557→                    fontSize: "20px",
 558→                    lineHeight: 1,
 559→                    padding: "0",
 560→                    transition: "background 0.1s",
 561→                    fontFamily: "inherit",
 562→                  }}
 563→                  onMouseEnter={(e) => {
 564→                    (e.currentTarget as HTMLButtonElement).style.background =
 565→                      "#e8f0fe";
 566→                  }}
 567→                  onMouseLeave={(e) => {
 568→                    (e.currentTarget as HTMLButtonElement).style.background =
 569→                      "none";
 570→                  }}
 571→                >
 572→                  +
 573→                </button>
 574→              </th>
 575→
 576→              {/* Row actions header spacer */}
 577→              <th
 578→                style={{
 579→                  background: "#f6f6f7",
 580→                  borderBottom: "2px solid #e1e3e5",
 581→                  width: "36px",
 582→                  minWidth: "36px",
 583→                }}
 584→              />
 585→            </tr>
 586→          </thead>
 587→          <tbody>
 588→            {data.rows.map((row, ri) => (
 589→              <tr
 590→                key={ri}
 591→                style={{
 592→                  background: ri % 2 === 0 ? "#ffffff" : "#fafbfb",
 593→                  transition: "background 0.1s",
 594→                }}
 595→                onMouseEnter={(e) => {
 596→                  (e.currentTarget as HTMLTableRowElement).style.background =
 597→                    "#f0f5ff";
 598→                }}
 599→                onMouseLeave={(e) => {
 600→                  (e.currentTarget as HTMLTableRowElement).style.background =
 601→                    ri % 2 === 0 ? "#ffffff" : "#fafbfb";
 602→                }}
 603→              >
 604→                {data.headers.map((header, hi) => (
 605→                  <td
 606→                    key={hi}
 607→                    style={{
 608→                      borderBottom:
 609→                        ri < data.rows.length - 1
 610→                          ? "1px solid #e1e3e5"
 611→                          : "none",
 612→                      borderRight:
 613→                        hi < data.headers.length - 1
 614→                          ? "1px solid #e1e3e5"
 615→                          : "none",
 616→                      padding: "0",
 617→                    }}
 618→                  >
 619→                    <input
 620→                      value={row[header] ?? ""}
 621→                      onChange={(e) =>
 622→                        updateCell(
 623→                          ri,
 624→                          header,
 625→                          (e.target as HTMLInputElement).value,
 626→                        )
 627→                      }
 628→                      style={{
 629→                        width: "100%",
 630→                        border: "none",
 631→                        background: "transparent",
 632→                        padding: "9px 10px",
 633→                        fontSize: "13px",
 634→                        color: "#202223",
 635→                        outline: "none",
 636→                        boxSizing: "border-box",
 637→                        fontFamily: "inherit",
 638→                      }}
 639→                      onFocus={(e) => {
 640→                        (
 641→                          e.target as HTMLInputElement
 642→                        ).parentElement!.style.boxShadow =
 643→                          "inset 0 0 0 2px #2c6ecb";
 644→                        (
 645→                          e.target as HTMLInputElement
 646→                        ).parentElement!.style.background = "#f0f5ff";
 647→                      }}
 648→                      onBlur={(e) => {
 649→                        (
 650→                          e.target as HTMLInputElement
 651→                        ).parentElement!.style.boxShadow = "none";
 652→                        (
 653→                          e.target as HTMLInputElement
 654→                        ).parentElement!.style.background = "transparent";
 655→                      }}
 656→                      placeholder="—"
 657→                    />
 658→                  </td>
 659→                ))}
 660→
 661→                {/* Column spacer — aligns under add column button */}
 662→                <td
 663→                  style={{
 664→                    borderBottom:
 665→                      ri < data.rows.length - 1 ? "1px solid #e1e3e5" : "none",
 666→                    borderRight: "1px solid #e1e3e5",
 667→                    width: "40px",
 668→                    background: "transparent",
 669→                  }}
 670→                />
 671→
 672→                {/* Remove row button */}
 673→                <td
 674→                  style={{
 675→                    borderBottom:
 676→                      ri < data.rows.length - 1 ? "1px solid #e1e3e5" : "none",
 677→                    padding: "0",
 678→                    textAlign: "center",
 679→                    width: "36px",
 680→                    background: "transparent",
 681→                  }}
 682→                >
 683→                  <button
 684→                    type="button"
 685→                    onClick={() => removeRow(ri)}
 686→                    title="Remove row"
 687→                    style={{
 688→                      background: "none",
 689→                      border: "none",
 690→                      cursor: "pointer",
 691→                      color: "#c9cccf",
 692→                      fontSize: "16px",
 693→                      lineHeight: 1,
 694→                      padding: "4px 8px",
 695→                      borderRadius: "4px",
 696→                      transition: "color 0.1s, background 0.1s",
 697→                      fontFamily: "inherit",
 698→                    }}
 699→                    onMouseEnter={(e) => {
 700→                      (e.currentTarget as HTMLButtonElement).style.color =
 701→                        "#d82c0d";
 702→                      (e.currentTarget as HTMLButtonElement).style.background =
 703→                        "#fee2e2";
 704→                    }}
 705→                    onMouseLeave={(e) => {
 706→                      (e.currentTarget as HTMLButtonElement).style.color =
 707→                        "#c9cccf";
 708→                      (e.currentTarget as HTMLButtonElement).style.background =
 709→                        "none";
 710→                    }}
 711→                  >
 712→                    &times;
 713→                  </button>
 714→                </td>
 715→              </tr>
 716→            ))}
