   1→import { useEffect, useRef, useState } from "react";
   2→import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
   3→import { useLoaderData, useFetcher, redirect, useNavigate } from "react-router";
   4→import { useAppBridge } from "@shopify/app-bridge-react";
   5→import { authenticate } from "../shopify.server";
   6→import db from "../db.server";
   7→import {
   8→  Page,
   9→  Layout,
  10→  Card,
  11→  BlockStack,
  12→  InlineStack,
  13→  Text,
  14→  Badge,
  15→  Button,
  16→  ButtonGroup,
  17→  Banner,
  18→  TextField,
  19→  Select,
  20→  Checkbox,
  21→  List,
  22→  Tabs,
  23→  ChoiceList,
  24→  ResourceList,
  25→  ResourceItem,
  26→  EmptyState,
  27→  Tooltip,
  28→} from "@shopify/polaris";
  29→
  30→// ---------------------------------------------------------------------------
  31→// Types
  32→// ---------------------------------------------------------------------------
  33→
  34→interface DisplaySettings {
  35→  priority: number;
  36→  countries: "all" | "selected";
  37→  selectedCountries: string;
  38→  buttonPosition: "floating" | "above_desc" | "below_desc";
  39→}
  40→
  41→interface ChartData {
  42→  headers: string[];
  43→  units: { default: string; available: string[] };
  44→  rows: Record<string, string>[];
  45→  displaySettings?: DisplaySettings;
  46→  recommendationEnabled?: boolean;
  47→}
  48→
  49→interface Assignment {
  50→  id: string;
  51→  assignmentType: string;
  52→  assignmentValue: string;
  53→}
  54→
  55→// ---------------------------------------------------------------------------
  56→// Loader
  57→// ---------------------------------------------------------------------------
  58→
  59→export const loader = async ({ request, params }: LoaderFunctionArgs) => {
  60→  const { session } = await authenticate.admin(request);
  61→  const shop = session.shop;
  62→  const id = params.id;
  63→
  64→  if (!id) throw new Response("Not found", { status: 404 });
  65→
  66→  if (id === "new") {
  67→    return {
  68→      chart: null as null,
  69→      assignments: [] as Assignment[],
  70→      isNew: true,
  71→    };
  72→  }
  73→
  74→  const chart = await db.sizeChart.findFirst({
  75→    where: { id, shop },
  76→    include: { assignments: true },
  77→  });
  78→
  79→  if (!chart) {
  80→    throw new Response("Not found", { status: 404 });
  81→  }
  82→
  83→  return {
  84→    chart: {
  85→      id: chart.id,
  86→      name: chart.name,
  87→      category: chart.category,
  88→      status: chart.status,
  89→      data: chart.data,
  90→      createdAt: chart.createdAt.toISOString(),
  91→      updatedAt: chart.updatedAt.toISOString(),
  92→    },
  93→    assignments: chart.assignments.map((a) => ({
  94→      id: a.id,
  95→      assignmentType: a.assignmentType,
  96→      assignmentValue: a.assignmentValue,
  97→    })),
  98→    isNew: false,
  99→  };
 100→};
 101→
 102→// ---------------------------------------------------------------------------
 103→// Action
 104→// ---------------------------------------------------------------------------
 105→
 106→export const action = async ({ request, params }: ActionFunctionArgs) => {
 107→  const { session } = await authenticate.admin(request);
 108→  const shop = session.shop;
 109→  const id = params.id;
 110→  if (!id) return { error: "Missing chart ID" };
 111→  const formData = await request.formData();
 112→  const intent = formData.get("intent") as string;
 113→
 114→  try {
 115→    switch (intent) {
 116→      case "save": {
 117→        const name = formData.get("name") as string;
 118→        const category = formData.get("category") as string;
 119→        const status = formData.get("status") as string;
 120→        const dataRaw = formData.get("data") as string;
 121→
 122→        if (!name?.trim()) return { error: "Chart name is required" };
 123→
 124→        let parsedData: ChartData;
 125→        try {
 126→          parsedData = JSON.parse(dataRaw) as ChartData;
 127→        } catch {
 128→          return { error: "Invalid chart data. Please try again." };
 129→        }
 130→
 131→        if (id === "new") {
 132→          const chart = await db.sizeChart.create({
 133→            data: {
 134→              shop,
 135→              name: name.trim(),
 136→              category,
 137→              status,
 138→              data: JSON.stringify(parsedData),
 139→            },
 140→          });
 141→          return redirect(`/app/size-charts/${chart.id}?saved=1`);
 142→        }
 143→
 144→        const existing = await db.sizeChart.findFirst({ where: { id, shop } });
 145→        if (!existing) return { error: "Chart not found" };
 146→
 147→        await db.sizeChart.updateMany({
 148→          where: { id, shop },
 149→          data: {
 150→            name: name.trim(),
 151→            category,
 152→            status,
 153→            data: JSON.stringify(parsedData),
 154→          },
 155→        });
 156→        return { ok: true, message: "Chart saved successfully" };
 157→      }
 158→
 159→      case "toggle-status": {
 160→        const chart = await db.sizeChart.findFirst({ where: { id, shop } });
 161→        if (!chart) return { error: "Chart not found" };
 162→        const newStatus = chart.status === "active" ? "draft" : "active";
 163→        await db.sizeChart.updateMany({ where: { id, shop }, data: { status: newStatus } });
 164→        return {
 165→          ok: true,
 166→          message: newStatus === "active" ? "Chart published" : "Chart unpublished",
 167→          newStatus,
 168→        };
 169→      }
 170→
 171→      case "add-assignment": {
 172→        const assignmentType = formData.get("assignmentType") as string;
 173→        const assignmentValue = formData.get("assignmentValue") as string;
 174→
 175→        if (!assignmentValue?.trim()) {
 176→          return { error: "Assignment value is required" };
 177→        }
 178→
 179→        await db.chartAssignment.upsert({
 180→          where: {
 181→            shop_sizeChartId_assignmentType_assignmentValue: {
 182→              shop,
 183→              sizeChartId: id,
 184→              assignmentType,
 185→              assignmentValue: assignmentValue.trim(),
 186→            },
 187→          },
 188→          create: {
 189→            shop,
 190→            sizeChartId: id,
 191→            assignmentType,
 192→            assignmentValue: assignmentValue.trim(),
 193→          },
 194→          update: {},
 195→        });
 196→        return { ok: true, message: "Assignment added" };
 197→      }
 198→
 199→      case "remove-assignment": {
 200→        const assignmentId = formData.get("assignmentId") as string;
 201→        await db.chartAssignment.deleteMany({
 202→          where: { id: assignmentId, shop },
 203→        });
 204→        return { ok: true, message: "Assignment removed" };
 205→      }
 206→
 207→      case "delete": {
 208→        await db.sizeChart.deleteMany({ where: { id, shop } });
 209→        return redirect("/app/size-charts");
 210→      }
 211→
 212→      default:
 213→        return { error: "Unknown action" };
 214→    }
 215→  } catch (error) {
 216→    const message =
 217→      error instanceof Error ? error.message : "An unexpected error occurred";
 218→    if (message.includes("Unique constraint")) {
 219→      return { error: "A chart with this name already exists." };
 220→    }
 221→    return { error: message };
 222→  }
 223→};
