 226→// Constants
 227→// ---------------------------------------------------------------------------
 228→
 229→const CATEGORIES = [
 230→  { value: "general", label: "General" },
 231→  { value: "tops", label: "Tops" },
 232→  { value: "bottoms", label: "Bottoms" },
 233→  { value: "dresses", label: "Dresses" },
 234→  { value: "shoes", label: "Shoes" },
 235→  { value: "kids", label: "Kids" },
 236→  { value: "rings", label: "Rings" },
 237→  { value: "sportswear", label: "Sportswear" },
 238→];
 239→
 240→const ASSIGNMENT_TYPES = [
 241→  { value: "product", label: "Product ID" },
 242→  { value: "collection", label: "Collection ID" },
 243→  { value: "tag", label: "Product Tag" },
 244→  { value: "product_type", label: "Product Type" },
 245→  { value: "all", label: "All Products" },
 246→];
 247→
 248→function formatDate(iso: string): string {
 249→  return new Date(iso).toLocaleDateString("en-US", {
 250→    month: "short",
 251→    day: "numeric",
 252→    year: "numeric",
 253→    hour: "2-digit",
 254→    minute: "2-digit",
 255→  });
 256→}
 257→
 258→function makeDefaultData(): ChartData {
 259→  return {
 260→    headers: ["Size", "Chest", "Waist", "Hips"],
 261→    units: { default: "in", available: ["in", "cm"] },
 262→    rows: [
 263→      { Size: "S", Chest: "", Waist: "", Hips: "" },
 264→      { Size: "M", Chest: "", Waist: "", Hips: "" },
 265→      { Size: "L", Chest: "", Waist: "", Hips: "" },
 266→    ],
 267→  };
 268→}
 269→
 270→function parseChartData(raw: string): ChartData {
 271→  try {
 272→    const parsed = JSON.parse(raw) as ChartData;
 273→    if (
 274→      Array.isArray(parsed.headers) &&
 275→      parsed.units &&
 276→      Array.isArray(parsed.rows)
 277→    ) {
 278→      return parsed;
 279→    }
 280→  } catch {
 281→    // fall through
 282→  }
 283→  return makeDefaultData();
 284→}
