 289→
 290→interface TableEditorProps {
 291→  data: ChartData;
 292→  onChange: (data: ChartData) => void;
 293→}
 294→
 295→function TableEditor({ data, onChange }: TableEditorProps) {
 296→  const headerInputRefs = useRef<(HTMLInputElement | null)[]>([]);
 297→
 298→  const updateCell = (rowIndex: number, header: string, value: string) => {
 299→    const newRows = data.rows.map((row, i) => {
 300→      if (i !== rowIndex) return row;
 301→      return { ...row, [header]: value };
 302→    });
 303→    onChange({ ...data, rows: newRows });
 304→  };
 305→
 306→  const updateHeader = (headerIndex: number, value: string) => {
 307→    const oldHeader = data.headers[headerIndex];
 308→    const newHeaders = data.headers.map((h, i) =>
 309→      i === headerIndex ? value : h,
 310→    );
 311→    const newRows = data.rows.map((row) => {
 312→      const newRow: Record<string, string> = {};
 313→      data.headers.forEach((h, i) => {
 314→        const key = i === headerIndex ? value : h;
 315→        newRow[key] = row[h] ?? "";
 316→      });
 317→      return newRow;
 318→    });
 319→    onChange({ ...data, headers: newHeaders, rows: newRows });
 320→    void oldHeader;
 321→  };
 322→
 323→  const addRow = () => {
 324→    const emptyRow: Record<string, string> = {};
 325→    data.headers.forEach((h) => {
 326→      emptyRow[h] = "";
 327→    });
 328→    onChange({ ...data, rows: [...data.rows, emptyRow] });
 329→  };
 330→
 331→  const removeRow = (rowIndex: number) => {
 332→    onChange({ ...data, rows: data.rows.filter((_, i) => i !== rowIndex) });
 333→  };
 334→
 335→  const addColumn = () => {
 336→    const newHeader = `Column ${data.headers.length + 1}`;
 337→    const newHeaders = [...data.headers, newHeader];
 338→    const newRows = data.rows.map((row) => ({ ...row, [newHeader]: "" }));
 339→    onChange({ ...data, headers: newHeaders, rows: newRows });
 340→  };
 341→
 342→  const removeColumn = (headerIndex: number) => {
 343→    if (data.headers.length <= 1) return;
 344→    const removedHeader = data.headers[headerIndex];
 345→    const newHeaders = data.headers.filter((_, i) => i !== headerIndex);
 346→    const newRows = data.rows.map((row) => {
 347→      const newRow: Record<string, string> = {};
 348→      newHeaders.forEach((h) => {
 349→        newRow[h] = row[h] ?? "";
 350→      });
 351→      return newRow;
 352→    });
 353→    onChange({ ...data, headers: newHeaders, rows: newRows });
 354→    void removedHeader;
 355→  };
 356→
 357→  const toggleUnit = (unit: string) => {
 358→    onChange({ ...data, units: { ...data.units, default: unit } });
 359→  };
 360→
 361→  return (
 362→    <BlockStack gap="300">
 363→      {/* Toolbar -- unit toggle + row/col count */}
 364→      <InlineStack gap="300" align="start" blockAlign="center">
 365→        <Text as="span" variant="bodySm" tone="subdued" fontWeight="semibold">
 366→          Units
 367→        </Text>
 368→        <ButtonGroup variant="segmented">
 369→          {data.units.available.map((unit) => (
 370→            <Button
 371→              key={unit}
 372→              pressed={data.units.default === unit}
 373→              onClick={() => toggleUnit(unit)}
 374→              size="slim"
 375→            >
 376→              {unit}
 377→            </Button>
 378→          ))}
 379→        </ButtonGroup>
 380→        <div style={{ marginLeft: "auto" }}>
 381→          <Badge>
 382→            {`${data.rows.length} rows \u00b7 ${data.headers.length} cols`}
 383→          </Badge>
 384→        </div>
 385→      </InlineStack>
 386→
 387→      {/* Table */}
 388→      <div
 389→        style={{
 390→          border: "1px solid #e1e3e5",
 391→          borderRadius: "8px",
 392→          overflow: "hidden",
 393→          overflowX: "auto",
 394→        }}
 395→      >
 396→        <table
 397→          style={{
 398→            width: "100%",
 399→            borderCollapse: "collapse",
 400→            fontSize: "13px",
 401→            tableLayout: "auto",
 402→          }}
 403→        >
 404→          <thead>
 405→            <tr>
 406→              {data.headers.map((header, hi) => (
 407→                <th
 408→                  key={hi}
 409→                  style={{
 410→                    background: "#f6f6f7",
 411→                    borderBottom: "2px solid #e1e3e5",
 412→                    borderRight:
 413→                      hi < data.headers.length - 1
 414→                        ? "1px solid #e1e3e5"
 415→                        : "none",
 416→                    padding: "0",
 417→                    position: "relative",
 418→                    minWidth: "110px",
 419→                  }}
 420→                >
 421→                  <div
 422→                    style={{
 423→                      display: "flex",
 424→                      alignItems: "center",
 425→                      padding: "2px 6px 2px 10px",
 426→                    }}
 427→                  >
 428→                    <input
 429→                      ref={(el) => {
 430→                        headerInputRefs.current[hi] = el;
 431→                      }}
 432→                      value={header}
 433→                      onChange={(e) =>
 434→                        updateHeader(hi, (e.target as HTMLInputElement).value)
 435→                      }
 436→                      style={{
 437→                        flex: 1,
 438→                        border: "none",
 439→                        background: "transparent",
 440→                        fontWeight: 700,
 441→                        fontSize: "12px",
 442→                        color: "#202223",
 443→                        padding: "8px 4px",
 444→                        outline: "none",
 445→                        minWidth: "60px",
 446→                        textTransform: "uppercase",
 447→                        letterSpacing: "0.04em",
 448→                        fontFamily: "inherit",
 449→                      }}
 450→                      placeholder={`Col ${hi + 1}`}
 451→                    />
 452→                    {data.headers.length > 1 && (
 453→                      <Tooltip content="Remove column" dismissOnMouseOut>
 454→                        <Button
 455→                          variant="plain"
 456→                          tone="critical"
 457→                          onClick={() => removeColumn(hi)}
 458→                          accessibilityLabel={`Remove column ${header}`}
 459→                          size="slim"
 460→                        >
 461→                          &times;
 462→                        </Button>
 463→                      </Tooltip>
 464→                    )}
 465→                  </div>
 466→                </th>
 467→              ))}
 468→
 469→              {/* Add column header cell */}
 470→              <th
 471→                style={{
 472→                  background: "#f6f6f7",
 473→                  borderBottom: "2px solid #e1e3e5",
 474→                  padding: "4px",
 475→                  width: "48px",
 476→                  minWidth: "48px",
 477→                  textAlign: "center",
 478→                }}
 479→              >
 480→                <Tooltip content="Add column" dismissOnMouseOut>
 481→                  <Button
 482→                    variant="plain"
 483→                    onClick={addColumn}
 484→                    accessibilityLabel="Add column"
 485→                    size="slim"
 486→                  >
 487→                    +
 488→                  </Button>
 489→                </Tooltip>
 490→              </th>
 491→
 492→              {/* Row actions header spacer */}
 493→              <th
 494→                style={{
 495→                  background: "#f6f6f7",
 496→                  borderBottom: "2px solid #e1e3e5",
 497→                  width: "36px",
 498→                  minWidth: "36px",
 499→                }}
 500→              />
 501→            </tr>
 502→          </thead>
 503→          <tbody>
 504→            {data.rows.map((row, ri) => (
 505→              <tr
 506→                key={ri}
 507→                style={{
 508→                  background: ri % 2 === 0 ? "#ffffff" : "#fafbfb",
 509→                  transition: "background 0.1s",
 510→                }}
 511→                onMouseEnter={(e) => {
 512→                  (e.currentTarget as HTMLTableRowElement).style.background =
 513→                    "#f0f5ff";
 514→                }}
 515→                onMouseLeave={(e) => {
 516→                  (e.currentTarget as HTMLTableRowElement).style.background =
 517→                    ri % 2 === 0 ? "#ffffff" : "#fafbfb";
 518→                }}
 519→              >
 520→                {data.headers.map((header, hi) => (
 521→                  <td
 522→                    key={hi}
 523→                    style={{
 524→                      borderBottom:
 525→                        ri < data.rows.length - 1
 526→                          ? "1px solid #e1e3e5"
 527→                          : "none",
 528→                      borderRight:
 529→                        hi < data.headers.length - 1
 530→                          ? "1px solid #e1e3e5"
 531→                          : "none",
 532→                      padding: "0",
 533→                    }}
 534→                  >
 535→                    <input
 536→                      value={row[header] ?? ""}
 537→                      onChange={(e) =>
 538→                        updateCell(
 539→                          ri,
 540→                          header,
 541→                          (e.target as HTMLInputElement).value,
 542→                        )
 543→                      }
 544→                      style={{
 545→                        width: "100%",
 546→                        border: "none",
 547→                        background: "transparent",
 548→                        padding: "9px 10px",
 549→                        fontSize: "13px",
 550→                        color: "#202223",
 551→                        outline: "none",
 552→                        boxSizing: "border-box",
 553→                        fontFamily: "inherit",
 554→                      }}
 555→                      onFocus={(e) => {
 556→                        (
 557→                          e.target as HTMLInputElement
 558→                        ).parentElement!.style.boxShadow =
 559→                          "inset 0 0 0 2px #2c6ecb";
 560→                        (
 561→                          e.target as HTMLInputElement
 562→                        ).parentElement!.style.background = "#f0f5ff";
 563→                      }}
 564→                      onBlur={(e) => {
 565→                        (
 566→                          e.target as HTMLInputElement
 567→                        ).parentElement!.style.boxShadow = "none";
 568→                        (
 569→                          e.target as HTMLInputElement
 570→                        ).parentElement!.style.background = "transparent";
 571→                      }}
 572→                      placeholder="—"
 573→                    />
 574→                  </td>
 575→                ))}
 576→
 577→                {/* Column spacer — aligns under add column button */}
 578→                <td
 579→                  style={{
 580→                    borderBottom:
 581→                      ri < data.rows.length - 1 ? "1px solid #e1e3e5" : "none",
 582→                    borderRight: "1px solid #e1e3e5",
 583→                    width: "40px",
 584→                    background: "transparent",
 585→                  }}
 586→                />
 587→
 588→                {/* Remove row button */}
 589→                <td
 590→                  style={{
 591→                    borderBottom:
 592→                      ri < data.rows.length - 1 ? "1px solid #e1e3e5" : "none",
 593→                    padding: "4px",
 594→                    textAlign: "center",
 595→                    width: "48px",
 596→                    background: "transparent",
 597→                  }}
 598→                >
 599→                  <Tooltip content="Remove row" dismissOnMouseOut>
 600→                    <Button
 601→                      variant="plain"
 602→                      tone="critical"
 603→                      onClick={() => removeRow(ri)}
 604→                      accessibilityLabel={`Remove row ${ri + 1}`}
 605→                      size="slim"
 606→                    >
 607→                      &times;
 608→                    </Button>
 609→                  </Tooltip>
 610→                </td>
 611→              </tr>
 612→            ))}
 613→
 614→            {/* Add row footer */}
 615→            <tr>
 616→              <td
 617→                colSpan={data.headers.length + 2}
 618→                style={{
 619→                  padding: "8px 12px",
 620→                  background: "#f6f6f7",
 621→                  borderTop: "1px solid #e1e3e5",
 622→                }}
 623→              >
 624→                <Button variant="plain" onClick={addRow}>
 625→                  + Add row
 626→                </Button>
 627→              </td>
 628→            </tr>
 629→          </tbody>
 630→        </table>
 631→      </div>
 632→    </BlockStack>
 633→  );
 634→}
