 644→type LoaderData = Awaited<ReturnType<typeof loader>>;
 645→type ActiveTab = "chart" | "assignments" | "position" | "recommendation" | "settings";
 646→
 647→export default function SizeChartEditor() {
 648→  const loaderData = useLoaderData<typeof loader>() as LoaderData;
 649→  const { chart, assignments: initialAssignments, isNew } = loaderData;
 650→  const navigate = useNavigate();
 651→
 652→  const saveFetcher = useFetcher<typeof action>();
 653→  const statusFetcher = useFetcher<typeof action>();
 654→  const assignmentFetcher = useFetcher<typeof action>();
 655→  const shopify = useAppBridge();
 656→
 657→  const [activeTab, setActiveTab] = useState<ActiveTab>("chart");
 658→  const [name, setName] = useState(chart?.name ?? "Untitled Size Chart");
 659→  const [category, setCategory] = useState(chart?.category ?? "general");
 660→  const [status, setStatus] = useState(chart?.status ?? "draft");
 661→  const [chartData, setChartData] = useState<ChartData>(
 662→    chart ? parseChartData(chart.data) : makeDefaultData(),
 663→  );
 664→  const [assignments, setAssignments] =
 665→    useState<Assignment[]>(initialAssignments);
 666→  const [newAssignmentType, setNewAssignmentType] = useState("product");
 667→  const [newAssignmentValue, setNewAssignmentValue] = useState("");
 668→
 669→  // Position settings (stored in chartData.displaySettings)
 670→  const _parsedSettings = chart ? parseChartData(chart.data).displaySettings : undefined;
 671→  const [priority, setPriority] = useState(_parsedSettings?.priority ?? 1);
 672→  const [countries, setCountries] = useState<"all" | "selected">(_parsedSettings?.countries ?? "all");
 673→  const [selectedCountries, setSelectedCountries] = useState(_parsedSettings?.selectedCountries ?? "");
 674→  const [buttonPosition, setButtonPosition] = useState<"floating" | "above_desc" | "below_desc">(_parsedSettings?.buttonPosition ?? "floating");
 675→  const [recommendationEnabled, setRecommendationEnabled] = useState(
 676→    chart ? (parseChartData(chart.data).recommendationEnabled ?? false) : false,
 677→  );
 678→
 679→  const isSaving = saveFetcher.state !== "idle";
 680→  const isTogglingStatus = statusFetcher.state !== "idle";
 681→
 682→  // Check for ?saved=1 on mount (after redirect from new chart creation)
 683→  useEffect(() => {
 684→    if (typeof window !== "undefined") {
 685→      const url = new URL(window.location.href);
 686→      if (url.searchParams.get("saved") === "1") {
 687→        shopify.toast.show("Chart created successfully");
 688→        url.searchParams.delete("saved");
 689→        window.history.replaceState({}, "", url.toString());
 690→      }
 691→    }
 692→  }, [shopify]);
 693→
 694→  // Save feedback
 695→  useEffect(() => {
 696→    if (!saveFetcher.data) return;
 697→    const data = saveFetcher.data;
 698→    if ("ok" in data && data.ok) {
 699→      shopify.toast.show(data.message ?? "Saved");
 700→    } else if ("error" in data) {
 701→      shopify.toast.show(data.error ?? "An error occurred", { isError: true });
 702→    }
 703→  }, [saveFetcher.data, shopify]);
 704→
 705→  // Status toggle feedback
 706→  useEffect(() => {
 707→    if (!statusFetcher.data) return;
 708→    const data = statusFetcher.data;
 709→    if ("ok" in data && data.ok) {
 710→      shopify.toast.show(data.message ?? "Status updated");
 711→      if ("newStatus" in data && typeof data.newStatus === "string") {
 712→        setStatus(data.newStatus);
 713→      }
 714→    } else if ("error" in data) {
 715→      shopify.toast.show(data.error ?? "An error occurred", { isError: true });
 716→    }
 717→  }, [statusFetcher.data, shopify]);
 718→
 719→  // Assignment feedback
 720→  useEffect(() => {
 721→    if (!assignmentFetcher.data) return;
 722→    const data = assignmentFetcher.data;
 723→    if ("ok" in data && data.ok) {
 724→      shopify.toast.show(data.message ?? "Done");
 725→      setNewAssignmentValue("");
 726→    } else if ("error" in data) {
 727→      shopify.toast.show(data.error ?? "An error occurred", { isError: true });
 728→    }
 729→  }, [assignmentFetcher.data, shopify]);
 730→
 731→  const handleSave = () => {
 732→    const formData = new FormData();
 733→    formData.set("intent", "save");
 734→    formData.set("name", name);
 735→    formData.set("category", category);
 736→    formData.set("status", status);
 737→    const fullData: ChartData = {
 738→      ...chartData,
 739→      displaySettings: { priority, countries, selectedCountries, buttonPosition },
 740→      recommendationEnabled,
 741→    };
 742→    formData.set("data", JSON.stringify(fullData));
 743→    saveFetcher.submit(formData, { method: "post" });
 744→  };
 745→
 746→  const handleToggleStatus = () => {
 747→    const formData = new FormData();
 748→    formData.set("intent", "toggle-status");
 749→    statusFetcher.submit(formData, { method: "post" });
 750→  };
 751→
 752→  const handleAddAssignment = () => {
 753→    if (!newAssignmentValue.trim() && newAssignmentType !== "all") return;
 754→    const formData = new FormData();
 755→    formData.set("intent", "add-assignment");
 756→    formData.set("assignmentType", newAssignmentType);
 757→    formData.set(
 758→      "assignmentValue",
 759→      newAssignmentType === "all" ? "*" : newAssignmentValue.trim(),
 760→    );
 761→    assignmentFetcher.submit(formData, { method: "post" });
 762→    setAssignments((prev) => [
 763→      ...prev,
 764→      {
 765→        id: `temp-${Date.now()}`,
 766→        assignmentType: newAssignmentType,
 767→        assignmentValue:
 768→          newAssignmentType === "all" ? "*" : newAssignmentValue.trim(),
 769→      },
 770→    ]);
 771→  };
 772→
 773→  const handleRemoveAssignment = (assignmentId: string) => {
 774→    const formData = new FormData();
 775→    formData.set("intent", "remove-assignment");
 776→    formData.set("assignmentId", assignmentId);
 777→    assignmentFetcher.submit(formData, { method: "post" });
 778→    setAssignments((prev) => prev.filter((a) => a.id !== assignmentId));
 779→  };
 780→
 781→  const assignmentTypeLabel = (type: string) =>
 782→    ASSIGNMENT_TYPES.find((t) => t.value === type)?.label ?? type;
 783→
 784→  const TAB_IDS: ActiveTab[] = ["chart", "assignments", "position", "recommendation", "settings"];
 785→  const tabDefinitions = [
 786→    { id: "chart", content: "Size Chart" },
 787→    { id: "assignments", content: `Assignments${assignments.length > 0 ? ` (${assignments.length})` : ""}` },
 788→    { id: "position", content: "Position" },
 789→    { id: "recommendation", content: "AI Recommendation" },
 790→    { id: "settings", content: "Settings" },
 791→  ];
 792→  const selectedTabIndex = TAB_IDS.indexOf(activeTab);
 793→  const handleTabSelect = (index: number) => {
 794→    setActiveTab(TAB_IDS[index]);
 795→  };
 796→
 797→  return (
 798→    <Page
 799→      title={isNew ? "New Size Chart" : name}
 800→      backAction={{ onAction: () => navigate("/app/size-charts") }}
 801→      primaryAction={
 802→        <Button
 803→          variant="primary"
 804→          onClick={handleSave}
 805→          loading={isSaving}
 806→          disabled={isSaving}
 807→        >
 808→          {isSaving ? "Saving..." : "Save"}
 809→        </Button>
 810→      }
 811→      secondaryActions={[
 812→        {
 813→          content: status === "active" ? "Unpublish" : "Publish",
 814→          onAction: handleToggleStatus,
 815→          loading: isTogglingStatus,
 816→          disabled: isNew || isTogglingStatus,
 817→        },
 818→      ]}
 819→    >
 820→      <Layout>
 821→        <Layout.Section>
 822→          <BlockStack gap="400">
 823→            {/* ============================================================ */}
 824→            {/* Tab navigation                                                */}
 825→            {/* ============================================================ */}
 826→            <Tabs
 827→              tabs={tabDefinitions}
 828→              selected={selectedTabIndex}
 829→              onSelect={handleTabSelect}
 830→              fitted
 831→            />
 832→
 833→            {/* ============================================================ */}
 834→            {/* TAB: Size Chart                                               */}
 835→            {/* ============================================================ */}
 836→            {activeTab === "chart" && (
 837→              <BlockStack gap="400">
 838→                {/* General Settings card */}
 839→                <Card>
 840→                  <BlockStack gap="400">
 841→                    <InlineStack gap="400" align="start" blockAlign="center">
 842→                      <Text as="h2" variant="headingMd" fontWeight="bold">
 843→                        General Settings
 844→                      </Text>
 845→                      <Badge tone={status === "active" ? "success" : "new"}>
 846→                        {status === "active" ? "Published" : "Draft"}
 847→                      </Badge>
 848→                    </InlineStack>
 849→                    <TextField
 850→                      label="Chart name"
 851→                      value={name}
 852→                      onChange={(value) => setName(value)}
 853→                      placeholder="e.g. Women's Tops Size Chart"
 854→                      autoComplete="off"
 855→                    />
 856→                    <Select
 857→                      label="Category"
 858→                      value={category}
 859→                      onChange={(value) => setCategory(value)}
 860→                      options={CATEGORIES}
 861→                    />
 862→                  </BlockStack>
 863→                </Card>
 864→
 865→                {/* Size Table card */}
 866→                <Card>
 867→                  <BlockStack gap="400">
 868→                    <BlockStack gap="200">
 869→                      <Text as="h2" variant="headingMd" fontWeight="bold">
 870→                        Size Table
 871→                      </Text>
 872→                      <Text as="p" variant="bodyMd" tone="subdued">
 873→                        Click any cell to edit. Click a column header to rename it. Use the + buttons to add rows or columns.
 874→                      </Text>
 875→                    </BlockStack>
